CREATE OR REPLACE FUNCTION public.prevent_posted_voucher_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op in ('UPDATE','DELETE') and old.posted = true and old.voided_at is null then
    raise exception 'Posted vouchers are immutable; create a reversal or adjustment voucher instead.';
  end if;
  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_posted_ledger_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op in ('UPDATE','DELETE') and old.posting_key is not null and old.voided_at is null then
    raise exception 'Posted ledger entries are immutable; create a reversal or adjustment voucher instead.';
  end if;
  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.finance_executive_dashboard_v3(p_start date, p_end date, p_previous_start date, p_previous_end date, p_trend_start date, p_entity_id text DEFAULT NULL::text, p_data_environment text DEFAULT 'production'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.finance_users%rowtype;v_entity text:=nullif(nullif(btrim(coalesce(p_entity_id,'')),''),'all');v_environment text:=coalesce(nullif(btrim(p_data_environment),''),'production');
 v_payload jsonb;v_ar jsonb;v_prev_ar jsonb;v_summary jsonb;
begin
 a:=private.finance_correction_actor_v1();
 if coalesce(public.current_finance_role(),'') not in ('accountant','ceo','admin_director','external_audit','board') then raise exception 'finance dashboard access denied' using errcode='42501';end if;
 v_payload:=public.finance_executive_dashboard_v2(p_start,p_end,p_previous_start,p_previous_end,p_trend_start,v_entity,v_environment);
 select jsonb_build_object('revenue',coalesce(sum(case when left(l.account_code,1) in ('4','7') then l.credit-l.debit else 0 end),0),
 'expense',coalesce(sum(case when left(l.account_code,1) in ('5','6','9') then l.debit-l.credit else 0 end),0),
 'net',coalesce(sum(case when left(l.account_code,1) in ('4','7') then l.credit-l.debit when left(l.account_code,1) in ('5','6','9') then l.credit-l.debit else 0 end),0),
 'ledgerRows',count(*),'balanceDiff',coalesce(sum(l.debit-l.credit),0),
 'missingSourceCount',count(*) filter(where coalesce(nullif(l.reference_no,''),nullif(l.source_no,''),nullif(l.source_id,''),nullif(l.voucher_no,''),nullif(l.posting_key,'')) is null)) into v_summary
 from public.ledger_entries l where l.tenant_id=a.tenant_id and l.data_environment=v_environment and l.voided_at is null and (v_entity is null or l.entity_id=v_entity) and l.entry_date between p_start and p_end;
 v_ar:=private.finance_receivables_payload_v1(p_end,v_entity,null,v_environment,true);
 v_prev_ar:=private.finance_receivables_payload_v1(p_previous_end,v_entity,null,v_environment,true);
 v_payload:=jsonb_set(jsonb_set(v_payload,'{version}','3'),'{summary}',v_summary);
 v_payload:=jsonb_set(v_payload,'{receivables}',jsonb_build_object(
  'total',(v_ar->'summary'->>'outstandingAmount')::numeric,
  'count',(select count(*) from jsonb_array_elements(v_ar->'items') x where (x->>'outstandingAmount')::numeric>0),
  'overdueTotal',(v_ar->'summary'->>'overdueAmount')::numeric,'over90Total',(v_ar->'summary'->>'over90Amount')::numeric,
  'unknownDue',(select count(*) from jsonb_array_elements(v_ar->'items') x where x->>'agingBucket'='unknown'),
  'buckets',v_ar->'buckets','reconciliation',v_ar->'reconciliation','complete',true,
  'items',(select coalesce(jsonb_agg(x||jsonb_build_object('key',x->>'invoiceNo','balance',(x->>'outstandingAmount')::numeric,'due',x->'dueDate')),'[]')
   from jsonb_array_elements(v_ar->'items') x where (x->>'outstandingAmount')::numeric>0)),true);
 v_payload:=jsonb_set(v_payload,'{previousReceivables}',jsonb_build_object('total',(v_prev_ar->'summary'->>'outstandingAmount')::numeric,
  'count',(select count(*) from jsonb_array_elements(v_prev_ar->'items') x where (x->>'outstandingAmount')::numeric>0)),true);
 return v_payload;
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_audit_source_v1(t uuid, e text, env text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 -- A complete-company count/digest must never expose the complement of a
 -- partially visible set. All rows (including voided/future rows) participate.
 with inv as materialized (
  select i.*,public.can_read_invoice(i) is true as readable from public.invoices i where i.tenant_id=t and i.entity_id=e and coalesce(i.data_environment,'production')=env
 ), req as materialized (
  select r.*,public.can_read_expense_request(r) is true as readable from public.expense_requests r where r.tenant_id=t and r.entity_id=e and coalesce(r.data_environment,'production')=env
 ), led as materialized (
  select l.* from public.ledger_entries l where l.tenant_id=t and l.entity_id=e and coalesce(l.data_environment,'production')=env
 ), dims as (
  select department_code from inv union select department_code from req union select department_code from led
 ), allowed as (
  select not exists(select 1 from inv where not readable) and not exists(select 1 from req where not readable)
   and not exists(select 1 from dims d where private.finance_expense_optional_permission_allows(t,public.current_finance_user_id(),'finance.request.view.all',
    jsonb_build_object('entity_id',e,'entityId',e,'legal_entity_code',e,'department_code',d.department_code,'departmentCode',d.department_code,'data_environment',env)) is distinct from true) as ok
 ), parts as (
  select 'invoices'::text as kind,count(*) as n,coalesce(string_agg(encode(sha256(convert_to((to_jsonb(i)-'readable')::text,'UTF8')),'hex'),'' order by i.id),'') as digest from inv i
  union all select 'expense_requests',count(*),coalesce(string_agg(encode(sha256(convert_to((to_jsonb(r)-'readable')::text,'UTF8')),'hex'),'' order by r.id),'') from req r
  union all select 'ledger',count(*),coalesce(string_agg(encode(sha256(convert_to(to_jsonb(l)::text,'UTF8')),'hex'),'' order by l.id),'') from led l
  union all select 'reporting_profile',count(*),coalesce(string_agg(encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex'),'' order by p.entity_id),'')
   from public.finance_reporting_profiles p where p.tenant_id=t and p.entity_id=e and p.data_environment=env
 ) select jsonb_build_object('allowed',(select ok from allowed),'fingerprint',encode(sha256(convert_to(t::text||'|'||e||'|'||env||'|'||string_agg(kind||':'||n||':'||digest,'|' order by kind),'UTF8')),'hex'),
  'counts',jsonb_object_agg(kind,n) filter(where kind<>'reporting_profile')) into result from parts;
 if result->>'allowed' is distinct from 'true' then raise exception '查帳來源未取得此公司全部資料的調閱權限' using errcode='42501';end if;
 return result-'allowed';
end $function$

CREATE OR REPLACE FUNCTION private.finance_next_voucher_no_for_tenant(p_tenant_id uuid, p_kind text, p_voucher_date date, p_data_environment text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_kind text;
  v_year integer;
  v_next integer;
  v_environment text;
begin
  if p_tenant_id is null then
    raise exception '產生傳票號碼時缺少租戶'
      using errcode = '22023';
  end if;

  v_kind := pg_catalog.upper(
    pg_catalog.regexp_replace(
      coalesce(nullif(p_kind, ''), 'V'),
      '[^A-Z0-9]',
      '',
      'g'
    )
  );
  if v_kind = '' then
    v_kind := 'V';
  end if;
  v_year := pg_catalog.date_part(
    'year',
    coalesce(p_voucher_date, current_date)
  )::integer;
  v_environment := pg_catalog.lower(coalesce(
    nullif(p_data_environment, ''),
    'production'
  ));

  if v_environment not in ('production', 'test') then
    raise exception '資料環境只允許 production 或 test'
      using errcode = '22023';
  end if;

  insert into public.voucher_serials (
    tenant_id,
    data_environment,
    kind,
    year,
    last_no,
    updated_at
  )
  values (
    p_tenant_id,
    v_environment,
    v_kind,
    v_year,
    1,
    pg_catalog.now()
  )
  on conflict (data_environment, kind, year)
  do update
     set last_no = public.voucher_serials.last_no + 1,
         updated_at = pg_catalog.now()
  returning last_no into v_next;

  return v_kind || v_year::text || '-' ||
    pg_catalog.lpad(v_next::text, 5, '0');
end;
$function$

CREATE OR REPLACE FUNCTION private.finance_ar_reconciliation_scope_v1(p_tenant uuid, p_environment text, p_as_of date, p_entity text, p_department text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.finance_users%rowtype; e text; dimensions record; found_company boolean:=false;
begin
 a:=private.finance_correction_actor_v1();
 if a.tenant_id is distinct from p_tenant or p_environment not in ('production','test') or p_as_of is null
  or coalesce(public.current_finance_role(),'') not in ('accountant','ceo','admin_director','external_audit','board') then return false;end if;
 -- Include the configured empty companies: no rows is not proof of authority.
 for e in
  select p_entity where nullif(p_entity,'all') is not null
  union
  select item->>'id' from public.system_settings s cross join lateral jsonb_array_elements(case when jsonb_typeof(s.value)='array' then s.value else '[]'::jsonb end) item
   where s.tenant_id=p_tenant and s.key='entities' and (p_entity is null or p_entity='all')
  union
  select l.entity_id from public.ledger_entries l where l.tenant_id=p_tenant and l.data_environment=p_environment and l.voided_at is null and l.entry_date<=p_as_of and l.account_code='1123'
   and (p_entity is null or p_entity='all' or l.entity_id=p_entity) and (p_department is null or l.department_code=p_department)
 loop
  if nullif(btrim(e),'') is null then return false;end if;
  begin perform private.finance_reporting_actor_v1(e,p_environment);
  exception when insufficient_privilege then return false;end;
  found_company:=true;
 end loop;
 if not found_company then return false;end if;
 if exists(select 1 from public.invoices i where i.tenant_id=p_tenant and i.data_environment=p_environment
  and (p_entity is null or p_entity='all' or i.entity_id=p_entity) and (p_department is null or i.department_code=p_department)
  and public.can_read_invoice(i) is distinct from true) then return false;end if;
 -- A company grant may still carry department restrictions. Check the exact
 -- ledger dimensions before exposing totals for unlinked invoice sources.
 for dimensions in select distinct l.entity_id,l.department_code from public.ledger_entries l
  where l.tenant_id=p_tenant and l.data_environment=p_environment and l.voided_at is null and l.entry_date<=p_as_of and l.account_code='1123'
   and (p_entity is null or p_entity='all' or l.entity_id=p_entity) and (p_department is null or l.department_code=p_department)
 loop
  if private.finance_expense_optional_permission_allows(p_tenant,a.id,'finance.request.view.all',jsonb_build_object(
    'entity_id',dimensions.entity_id,'entityId',dimensions.entity_id,'legal_entity_code',dimensions.entity_id,
    'department_code',dimensions.department_code,'departmentCode',dimensions.department_code,'data_environment',p_environment)) is distinct from true then return false;end if;
 end loop;
 return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.next_voucher_no(p_kind text DEFAULT 'V'::text, p_voucher_date date DEFAULT CURRENT_DATE, p_data_environment text DEFAULT 'production'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant_id uuid;
  v_kind text;
  v_year int;
  v_next int;
  v_environment text;
begin
  v_tenant_id := private.finance_require_authenticated_tenant();
  perform public.assert_accounting_actor();

  v_kind := pg_catalog.upper(
    pg_catalog.regexp_replace(
      coalesce(nullif(p_kind, ''), 'V'),
      '[^A-Z0-9]',
      '',
      'g'
    )
  );
  if v_kind = '' then
    v_kind := 'V';
  end if;

  v_year := pg_catalog.date_part(
    'year',
    coalesce(p_voucher_date, current_date)
  )::int;
  v_environment :=
    pg_catalog.lower(coalesce(nullif(p_data_environment, ''), 'production'));

  if v_environment not in ('production', 'test') then
    raise exception '資料環境只允許 production 或 test'
      using errcode = '22023';
  end if;

  insert into public.voucher_serials (
    tenant_id,
    data_environment,
    kind,
    year,
    last_no,
    updated_at
  )
  values (
    v_tenant_id,
    v_environment,
    v_kind,
    v_year,
    1,
    pg_catalog.now()
  )
  on conflict (data_environment, kind, year)
  do update
     set last_no = public.voucher_serials.last_no + 1,
         updated_at = pg_catalog.now()
  returning last_no into v_next;

  return v_kind || v_year::text || '-' ||
    pg_catalog.lpad(v_next::text, 5, '0');
end;
$function$

CREATE OR REPLACE FUNCTION public.post_adjustment_voucher(p_source_voucher_id text, p_reason text, p_entries jsonb, p_voucher_date date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  src public.vouchers%rowtype;
  entry jsonb;
  entry_idx int := 0;
  entry_type text;
  entry_account text;
  entry_name text;
  entry_dept text;
  entry_amount numeric;
  debit_total numeric := 0;
  credit_total numeric := 0;
  post_date date;
  adj_no text;
  adj_desc text;
  adj_type text := 'adjustment';
  src_env text;
begin
  perform public.assert_accounting_actor();
  if coalesce(trim(p_reason),'') = '' then raise exception 'Adjustment reason is required'; end if;
  if p_entries is null or jsonb_typeof(p_entries) <> 'array' or jsonb_array_length(p_entries)=0 then raise exception 'Adjustment entries are required'; end if;
  select * into src from public.vouchers where id=p_source_voucher_id for share;
  if not found then raise exception 'Source voucher not found: %', p_source_voucher_id; end if;
  if src.voided_at is not null then raise exception 'Voided source voucher cannot be adjusted: %', src.no; end if;
  post_date := coalesce(p_voucher_date,current_date);
  src_env := coalesce(src.data_environment,'production');
  for entry in select * from jsonb_array_elements(p_entries) loop
    entry_idx := entry_idx + 1;
    entry_type := lower(coalesce(entry ->> 't', entry ->> 'type', ''));
    entry_account := nullif(entry ->> 'ac', '');
    entry_name := coalesce(nullif(entry ->> 'an',''), nullif(entry ->> 'account_name',''), entry_account);
    entry_amount := coalesce(nullif(entry ->> 'amt','')::numeric, nullif(entry ->> 'amount','')::numeric, 0);
    if entry_type not in ('dr','cr') then raise exception 'Invalid adjustment entry type at row %', entry_idx; end if;
    if entry_account is null then raise exception 'Adjustment account is required at row %', entry_idx; end if;
    if entry_amount <= 0 then raise exception 'Adjustment amount must be positive at row %', entry_idx; end if;
    if entry_type='dr' then debit_total := debit_total + entry_amount; else credit_total := credit_total + entry_amount; end if;
  end loop;
  if round(debit_total-credit_total,2) <> 0 then raise exception 'Adjustment voucher is not balanced: debit %, credit %', debit_total, credit_total; end if;
  if trim(p_reason) like '沖銷 %' then adj_type := 'reversal'; end if;
  adj_no := public.next_voucher_no(case when adj_type='reversal' then 'RV' else 'ADJ' end, post_date, src_env);
  adj_desc := case when adj_type='reversal' then trim(p_reason) else '調整 '||src.no||' — '||trim(p_reason) end;
  insert into public.vouchers(id,no,request_id,entity_id,entity_name,voucher_date,description,entries,total,creator,posted,posted_at,posting_locked_at,adjusts_voucher_no,adjustment_type,data_environment)
  values (adj_no,adj_no,src.request_id,src.entity_id,src.entity_name,post_date,adj_desc,p_entries,debit_total,coalesce(public.current_finance_user_name(),'system'),true,now(),now(),src.no,adj_type,src_env);
  entry_idx := 0;
  for entry in select * from jsonb_array_elements(p_entries) loop
    entry_idx := entry_idx + 1;
    entry_type := lower(coalesce(entry ->> 't', entry ->> 'type', ''));
    entry_account := nullif(entry ->> 'ac', '');
    entry_name := coalesce(nullif(entry ->> 'an',''), nullif(entry ->> 'account_name',''), entry_account);
    entry_dept := coalesce(nullif(entry ->> 'dept',''), nullif(entry ->> 'department_code',''));
    entry_amount := coalesce(nullif(entry ->> 'amt','')::numeric, nullif(entry ->> 'amount','')::numeric, 0);
    insert into public.ledger_entries(entry_date,description,entity_id,department_code,debit,credit,account_code,account_name,reference_no,posting_key,source_type,source_id,source_no,voucher_no,data_environment)
    values (post_date,adj_desc,src.entity_id,entry_dept,case when entry_type='dr' then entry_amount else 0 end,case when entry_type='cr' then entry_amount else 0 end,entry_account,entry_name,adj_no,'voucher:'||adj_no||':'||entry_idx||':'||entry_account||':'||entry_type,'adjustment_voucher',adj_no,adj_no,adj_no,src_env)
    on conflict (data_environment, posting_key) where posting_key is not null do nothing;
  end loop;
  return jsonb_build_object('ok',true,'voucher_id',adj_no,'voucher_no',adj_no,'total',debit_total);
end;
$function$

CREATE OR REPLACE FUNCTION public.reverse_voucher(p_voucher_id text, p_reason text, p_reversal_date date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  src public.vouchers%rowtype;
  existing public.vouchers%rowtype;
  row public.ledger_entries%rowtype;
  entries jsonb := '[]'::jsonb;
  src_env text;
begin
  perform public.assert_accounting_actor();
  if coalesce(trim(p_reason),'') = '' then raise exception 'Reversal reason is required'; end if;
  select * into src from public.vouchers where id=p_voucher_id for share;
  if not found then raise exception 'Source voucher not found: %', p_voucher_id; end if;
  if src.voided_at is not null then raise exception 'Voided source voucher cannot be reversed: %', src.no; end if;
  src_env := coalesce(src.data_environment,'production');
  select * into existing from public.vouchers where adjusts_voucher_no=src.no and adjustment_type='reversal' and coalesce(data_environment,'production')=src_env order by created_at asc limit 1;
  if found then return jsonb_build_object('ok',true,'idempotent',true,'voucher_id',existing.id,'voucher_no',existing.no); end if;
  for row in select * from public.ledger_entries where voucher_no=src.no and coalesce(data_environment,'production')=src_env and voided_at is null order by id asc loop
    if row.debit > 0 then entries := entries || jsonb_build_array(jsonb_build_object('t','cr','ac',row.account_code,'an',coalesce(row.account_name,row.account_code),'dept',coalesce(row.department_code,''),'amt',row.debit)); end if;
    if row.credit > 0 then entries := entries || jsonb_build_array(jsonb_build_object('t','dr','ac',row.account_code,'an',coalesce(row.account_name,row.account_code),'dept',coalesce(row.department_code,''),'amt',row.credit)); end if;
  end loop;
  if jsonb_array_length(entries)=0 then
    entries := (select coalesce(jsonb_agg(jsonb_build_object('t',case when lower(e.value ->> 't')='dr' then 'cr' else 'dr' end,'ac',e.value ->> 'ac','an',coalesce(e.value ->> 'an', e.value ->> 'ac'),'dept',coalesce(e.value ->> 'dept',''),'amt',coalesce(nullif(e.value ->> 'amt','')::numeric,0))),'[]'::jsonb) from jsonb_array_elements(coalesce(src.entries,'[]'::jsonb)) as e(value) where coalesce(nullif(e.value ->> 'amt','')::numeric,0)>0);
  end if;
  return public.post_adjustment_voucher(src.id,'沖銷 '||src.no||' — '||trim(p_reason),entries,coalesce(p_reversal_date,current_date));
end;
$function$
